-- One-time password reset tokens, generated by admins and handed to users
-- out-of-band (Telegram, in person). No email involved.

create table if not exists public.password_reset_tokens (
  token        text primary key,
  user_id      uuid not null references auth.users(id) on delete cascade,
  created_by   uuid references auth.users(id) on delete set null,
  created_at   timestamptz not null default now(),
  expires_at   timestamptz not null,
  used_at      timestamptz
);

create index if not exists password_reset_tokens_user_idx
  on public.password_reset_tokens (user_id);

create index if not exists password_reset_tokens_expires_idx
  on public.password_reset_tokens (expires_at)
  where used_at is null;

-- Locked down: only service-role touches this table. Regular users must never
-- read or write here — the token itself is the only auth material.
alter table public.password_reset_tokens enable row level security;
